import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.DhF4LrUq.js";const r="/shipperdog/snapshot/screenshots/portal/catalog.png",n="/shipperdog/snapshot/screenshots/portal/version-detail.png",b=JSON.parse('{"title":"Browse your applications","description":"Browse your applications in the Tester Portal - what each card, version, and badge means.","frontmatter":{"description":"Browse your applications in the Tester Portal - what each card, version, and badge means."},"headers":[],"relativePath":"how-to/portal/browse-apps.md","filePath":"how-to/portal/browse-apps.md"}'),i={name:"how-to/portal/browse-apps.md"};function p(l,e,d,h,c,g){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="browse-your-applications" tabindex="-1">Browse your applications <a class="header-anchor" href="#browse-your-applications" aria-label="Permalink to &quot;Browse your applications&quot;">​</a></h1><p>Sign in and you are on <strong>My Applications</strong>: one card per app your team has shared with you. Tap a card to see its builds; that is the whole screen.</p><p><img src="'+r+'" alt="My Applications - one card per shared app"></p><h2 id="what-a-card-tells-you" tabindex="-1">What a card tells you <a class="header-anchor" href="#what-a-card-tells-you" aria-label="Permalink to &quot;What a card tells you&quot;">​</a></h2><ul><li><strong>App name</strong> and its <strong>latest version</strong> you are allowed to install.</li><li>A <strong>badge</strong> next to the version saying where that build stands: <strong>Draft</strong> (still being prepared — safe to install, earliest feedback wins), <strong>Active</strong> (ready and being tested), <strong>Archived</strong> (an old build, kept for reference), or <strong>Revoked</strong> (pulled back — expect a newer one soon).</li><li><strong>Platform chips</strong> — <code>Android</code>, <code>iOS</code> — showing which platforms have a build ready. No chip, no build for that platform yet.</li></ul><p><strong>Refresh</strong> re-checks for new builds; if there are more apps than fit, <strong>Load more</strong> appears at the bottom.</p><p>Tap a card and you see the app&#39;s builds, newest first — each with its badge, build number, file size, and upload date, plus the <strong>Download</strong> and <strong>Report issue</strong> buttons. Every build has its own shareable page, which is handy when you and the team are talking about exactly one build.</p><p><img src="'+n+'" alt="A build&#39;s page - badge, facts, download, report"></p><h2 id="if-the-list-is-empty" tabindex="-1">If the list is empty <a class="header-anchor" href="#if-the-list-is-empty" aria-label="Permalink to &quot;If the list is empty&quot;">​</a></h2><p>An empty list is not an error. It means nothing has been shared with you yet — ask your team to add you, then tap <strong>Refresh</strong>. You only ever see apps you are authorized to test; nothing else exists on this screen for you.</p><p><strong>Next:</strong> pick a card, then <a href="/shipperdog/snapshot/how-to/portal/install-android">install on Android</a> or <a href="/shipperdog/snapshot/how-to/portal/install-ios">install on iOS</a>.</p>',11)])])}const y=t(i,[["render",p]]);export{b as __pageData,y as default};
